content.content:
0	@import "tailwindcss";
1	@import "tw-animate-css";
2	@import "shadcn/tailwind.css";
3	
4	@custom-variant dark (&:is(.dark *));
5	
6	@theme inline {
7	  /* ──────────────────────────────────────────────────────────
8	     BRAND SWATCHES (single source of raw hex — Vega owns these)
9	  ────────────────────────────────────────────────────────── */
10	  --color-ink-black: #0a0a0f;
11	  --color-electric-purple: #7c3aed;
12	
13	  /* ──────────────────────────────────────────────────────────
14	     SEMANTIC PALETTE — LIGHT MODE
15	  ────────────────────────────────────────────────────────── */
16	
17	  /* Page canvas — warm off-white so cards "float" on it */
18	  --color-background: oklch(97.5% 0.003 264);
19	
20	  /* Text — near-black with a cool blue tint */
21	  --color-foreground: oklch(13% 0.015 264);
22	
23	  /* Card surface — pure white, visible against the page bg */
24	  --color-card: oklch(100% 0 0);
25	  --color-card-foreground: oklch(13% 0.015 264);
26	
27	  --color-popover: oklch(100% 0 0);
28	  --color-popover-foreground: oklch(13% 0.015 264);
29	
30	  /* Primary — same purple, unchanged */
31	  --color-primary: oklch(52% 0.24 292);
32	  --color-primary-foreground: oklch(99% 0 0);
33	
34	  /* Secondary — subtle lavender tint */
35	  --color-secondary: oklch(95.5% 0.012 292);
36	  --color-secondary-foreground: oklch(28% 0.06 292);
37	
38	  /* Muted — for backgrounds of non-interactive elements */
39	  --color-muted: oklch(95% 0.006 264);
40	  --color-muted-foreground: oklch(52% 0.02 264);
41	
42	  /* Accent — light purple for hover states and chips */
43	  --color-accent: oklch(95% 0.018 292);
44	  --color-accent-foreground: oklch(35% 0.14 292);
45	
46	  /* Destructive — unchanged */
47	  --color-destructive: oklch(59% 0.22 27);
48	  --color-destructive-foreground: oklch(99% 0 0);
49	
50	  /* ──────────────────────────────────────────────────────────
51	     SEMANTIC STATUS TOKENS
52	  ────────────────────────────────────────────────────────── */
53	  --color-success:            oklch(58% 0.18 145);
54	  --color-success-bg:         oklch(94% 0.05 145);
55	  --color-success-foreground: oklch(26% 0.12 145);
56	  --color-warning:            oklch(70% 0.16 72);
57	  --color-warning-bg:         oklch(94% 0.07 72);
58	  --color-warning-foreground: oklch(36% 0.15 72);
59	
60	  /* Borders — visible but light */
61	  --color-border: oklch(91% 0.008 264);
62	  --color-input: oklch(91% 0.008 264);
63	  --color-ring: oklch(52% 0.24 292);
64	
65	  /* ──────────────────────────────────────────────────────────
66	     SHADOWS — custom (never use Tailwind default shadow-sm/md)
67	  ────────────────────────────────────────────────────────── */
68	
69	  /* Soft border shadow for cards on white */
70	  --shadow-soft: 0 1px 2px 0 oklch(13% 0.015 264 / 0.05), 0 1px 3px 0 oklch(13% 0.015 264 / 0.04);
71	
72	  /* Standard card elevation — visible on off-white page */
73	  --shadow-card: 0 1px 3px 0 oklch(13% 0.015 264 / 0.07), 0 1px 2px -1px oklch(13% 0.015 264 / 0.05);
74	
75	  /* Hover elevation */
76	  --shadow-card-hover: 0 4px 12px -2px oklch(13% 0.015 264 / 0.10), 0 2px 6px -2px oklch(13% 0.015 264 / 0.07);
77	
78	  /* Medium depth for drawers, modals */
79	  --shadow-soft-md: 0 4px 16px -4px oklch(13% 0.015 264 / 0.10), 0 2px 8px -2px oklch(13% 0.015 264 / 0.07);
80	
81	  /* Floating elements — command palette, toasts, tooltips */
82	  --shadow-lift: 0 8px 24px -4px oklch(13% 0.015 264 / 0.14),
83	                 0 4px 10px -2px oklch(13% 0.015 264 / 0.08);
84	
85	  /* Full-screen overlays — modal backdrop shadow on dialog */
86	  --shadow-overlay: 0 24px 64px -12px oklch(13% 0.015 264 / 0.22),
87	                    0 8px 24px -4px oklch(13% 0.015 264 / 0.12);
88	
89	  /* ──────────────────────────────────────────────────────────
90	     RADIUS
91	  ────────────────────────────────────────────────────────── */
92	  --radius: 0.5rem;
93	  --radius-sm: 0.25rem;
94	  --radius-md: 0.5rem;
95	  --radius-lg: 0.75rem;
96	  --radius-xl: 1rem;
97	  --radius-2xl: 1.5rem;   /* 24px — large modals, full-bleed cards */
98	  --radius-full: 9999px;  /* pill buttons, avatar chips, progress bars */
99	
100	  /* ──────────────────────────────────────────────────────────
101	     TYPOGRAPHY
102	  ────────────────────────────────────────────────────────── */
103	  --font-sans: var(--font-geist-sans), system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
104	  --font-mono: var(--font-geist-mono), "Fira Code", "Cascadia Code", ui-monospace, monospace;
105	
106	  /* ──────────────────────────────────────────────────────────
107	     TYPOGRAPHY SCALE — semantic names
108	  ────────────────────────────────────────────────────────── */
109	  --text-display-size:    2.25rem;  /* 36px */
110	  --text-display-height:  2.5rem;   /* 40px */
111	  --text-display-weight:  700;
112	  --text-display-track:   -0.02em;
113	
114	  --text-h1-size:    1.75rem;       /* 28px */
115	  --text-h1-height:  2rem;          /* 32px */
116	  --text-h1-weight:  700;
117	  --text-h1-track:   -0.015em;
118	
119	  --text-h2-size:    1.25rem;       /* 20px */
120	  --text-h2-height:  1.75rem;       /* 28px */
121	  --text-h2-weight:  600;
122	  --text-h2-track:   -0.01em;
123	
124	  --text-h3-size:    1rem;          /* 16px */
125	  --text-h3-height:  1.5rem;        /* 24px */
126	  --text-h3-weight:  600;
127	  --text-h3-track:   -0.005em;
128	
129	  --text-body-size:    0.875rem;    /* 14px */
130	  --text-body-height:  1.25rem;     /* 20px */
131	  --text-body-weight:  400;
132	  --text-body-track:   0em;
133	
134	  --text-body-sm-size:    0.8125rem; /* 13px */
135	  --text-body-sm-height:  1.125rem;  /* 18px */
136	  --text-body-sm-weight:  400;
137	  --text-body-sm-track:   0em;
138	
139	  --text-caption-size:    0.75rem;  /* 12px */
140	  --text-caption-height:  1rem;     /* 16px */
141	  --text-caption-weight:  400;
142	  --text-caption-track:   0em;
143	
144	  --text-micro-size:    0.625rem;   /* 10px */
145	  --text-micro-height:  0.875rem;   /* 14px */
146	  --text-micro-weight:  500;
147	  --text-micro-track:   0.06em;     /* uppercase tracking */
148	
149	  /* ──────────────────────────────────────────────────────────
150	     SPACING CONSTANTS — semantic aliases
151	  ────────────────────────────────────────────────────────── */
152	  --spacing-page-x:      1.5rem;   /* px-6 — desktop page horizontal padding */
153	  --spacing-page-x-sm:   1rem;     /* px-4 — mobile page horizontal padding */
154	  --spacing-page-y:      1.5rem;   /* py-6 — vertical section gap */
155	  --spacing-card-pad:    1.5rem;   /* p-6  — card internal padding */
156	  --spacing-card-gap:    1rem;     /* gap-4 — gap between cards in a grid */
157	  --spacing-section-gap: 1.5rem;   /* space-y-6 — between page sections */
158	  --spacing-field-gap:   1rem;     /* space-y-4 — between form fields */
159	
160	  /* ──────────────────────────────────────────────────────────
161	     ICON SIZE SCALE — reference constants (see lib/design-tokens.ts)
162	  ────────────────────────────────────────────────────────── */
163	  --icon-xs:  0.75rem;   /* 12px */
164	  --icon-sm:  0.875rem;  /* 14px */
165	  --icon-md:  1rem;      /* 16px */
166	  --icon-lg:  1.25rem;   /* 20px */
167	  --icon-xl:  1.5rem;    /* 24px */
168	  --icon-2xl: 2rem;      /* 32px */
169	
170	  /* ──────────────────────────────────────────────────────────
171	     SIDEBAR TOKENS (shadcn sidebar primitives)
172	  ────────────────────────────────────────────────────────── */
173	  --sidebar: oklch(100% 0 0);
174	  --sidebar-background: oklch(100% 0 0);
175	  --sidebar-foreground: oklch(22% 0.015 264);
176	  --sidebar-primary: oklch(52% 0.24 292);
177	  --sidebar-primary-foreground: oklch(99% 0 0);
178	  --sidebar-accent: oklch(95.5% 0.018 292);
179	  --sidebar-accent-foreground: oklch(35% 0.14 292);
180	  --sidebar-border: oklch(91% 0.008 264);
181	  --sidebar-ring: oklch(52% 0.24 292);
182	  --sidebar-width: 15rem;
183	  --sidebar-width-mobile: 18rem;
184	  --sidebar-width-icon: 3.5rem;
185	
186	  /* shadcn token aliases */
187	  --color-sidebar: var(--sidebar);
188	  --color-sidebar-foreground: var(--sidebar-foreground);
189	  --color-sidebar-primary: var(--sidebar-primary);
190	  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
191	  --color-sidebar-accent: var(--sidebar-accent);
192	  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
193	  --color-sidebar-border: var(--sidebar-border);
194	  --color-sidebar-ring: var(--sidebar-ring);
195	
196	  /* ──────────────────────────────────────────────────────────
197	     PAGE LAYOUT — light mode
198	  ────────────────────────────────────────────────────────── */
199	  --color-page-bg: oklch(97.5% 0.003 264);
200	  --color-header-bg: oklch(100% 0 0);
201	  --color-surface-1: oklch(100% 0 0);
202	  --color-surface-2: oklch(97.5% 0.003 264);
203	
204	  /* ──────────────────────────────────────────────────────────
205	     STATUS BADGES — tattoo booking lifecycle
206	  ────────────────────────────────────────────────────────── */
207	  --color-status-pending: oklch(70% 0.16 72);
208	  --color-status-confirmed: oklch(62% 0.24 292);
209	  --color-status-in-progress: oklch(60% 0.2 200);
210	  --color-status-completed: oklch(58% 0.18 145);
211	  --color-status-cancelled: oklch(55% 0.02 264);
212	  --color-status-no-show: oklch(55% 0.22 27);
213	
214	  /* ──────────────────────────────────────────────────────────
215	     NEON ACCENT
216	  ────────────────────────────────────────────────────────── */
217	  --color-neon-purple: oklch(72% 0.28 292);
218	  --color-neon-purple-glow: 0 0 20px oklch(72% 0.28 292 / 0.4);
219	
220	  /* ──────────────────────────────────────────────────────────
221	     CONSENT — submission status colors (Sprint 5)
222	  ────────────────────────────────────────────────────────── */
223	  --color-consent-signed:       oklch(58% 0.18 145);
224	  --color-consent-pending:      oklch(70% 0.16 72);
225	  --color-consent-expired:      oklch(55% 0.02 264);
226	  --color-consent-deleted:      oklch(45% 0.02 264);
227	  --color-consent-opened:       oklch(60% 0.22 230);
228	
229	  /* ──────────────────────────────────────────────────────────
230	     CONSENT — template kind badge colors
231	  ────────────────────────────────────────────────────────── */
232	  --color-kind-tattoo:   oklch(62% 0.24 292);
233	  --color-kind-piercing: oklch(60% 0.22 230);
234	  --color-kind-pmu:      oklch(60% 0.24 340);
235	  --color-kind-touchup:  oklch(70% 0.16 72);
236	  --color-kind-minor:    oklch(55% 0.22 27);
237	
238	  /* ──────────────────────────────────────────────────────────
239	     CONSENT — signature pad
240	  ────────────────────────────────────────────────────────── */
241	  --color-sig-bg:              oklch(6% 0.01 264);
242	  --color-sig-stroke:          oklch(97% 0.01 264);
243	  --color-sig-border:          oklch(28% 0.04 292);
244	  --color-sig-border-active:   oklch(62% 0.24 292 / 0.6);
245	
246	  /* ──────────────────────────────────────────────────────────
247	     CONSENT — public signing page
248	  ────────────────────────────────────────────────────────── */
249	  --color-signing-bg:              oklch(8% 0.01 264);
250	  --color-signing-card:            oklch(12% 0.02 264);
251	  --color-signing-progress-track:  oklch(20% 0.02 264);
252	  --color-signing-progress-fill:   var(--studio-brand-color, oklch(62% 0.24 292));
253	
254	  /* ──────────────────────────────────────────────────────────
255	     CONSENT — template builder
256	  ────────────────────────────────────────────────────────── */
257	  --color-builder-panel-bg:       oklch(10% 0.015 264);
258	  --color-builder-section-bg:     oklch(14% 0.02 264);
259	  --color-builder-section-hover:  oklch(17% 0.025 264);
260	  --color-builder-section-drag:   oklch(12% 0.015 264 / 0.8);
261	  --color-builder-palette-item:   oklch(16% 0.02 264);
262	
263	  /* ──────────────────────────────────────────────────────────
264	     CONSENT — REACH disclosure
265	  ────────────────────────────────────────────────────────── */
266	  --color-reach-bg:     oklch(12% 0.03 292 / 0.4);
267	  --color-reach-border: oklch(62% 0.24 292 / 0.2);
268	
269	  /* ──────────────────────────────────────────────────────────
270	     RETENTION COUNTDOWN
271	  ────────────────────────────────────────────────────────── */
272	  --color-retention-safe: oklch(55% 0.02 264);
273	  --color-retention-warn: oklch(70% 0.16 72);
274	  --color-retention-crit: oklch(55% 0.22 27);
275	
276	  /* ──────────────────────────────────────────────────────────
277	     ANIMATIONS
278	  ────────────────────────────────────────────────────────── */
279	  --animate-fade-in-up: fade-in-up 0.35s ease-out;
280	  --animate-fade-in: fade-in 0.2s ease-out;
281	  --animate-slide-in-right: slide-in-right 0.25s ease-out;
282	
283	  @keyframes fade-in-up {
284	    from { opacity: 0; transform: translateY(6px); }
285	    to   { opacity: 1; transform: translateY(0); }
286	  }
287	  @keyframes fade-in {
288	    from { opacity: 0; }
289	    to   { opacity: 1; }
290	  }
291	  @keyframes slide-in-right {
292	    from { opacity: 0; transform: translateX(8px); }
293	    to   { opacity: 1; transform: translateX(0); }
294	  }
295	
296	  /* ──────────────────────────────────────────────────────────
297	     ONBOARDING PROGRESS
298	  ────────────────────────────────────────────────────────── */
299	  --color-onboarding-track: oklch(22% 0.02 264);

598	  /* ──────────────────────────────────────────────────────────
599	     LOCKED FORM BADGE (Sprint 8)
600	  ────────────────────────────────────────────────────────── */
601	  --color-locked-bg:     oklch(55% 0.02 264 / 0.12);
602	  --color-locked-text:   oklch(65% 0.02 264);
603	  --color-locked-border: oklch(55% 0.02 264 / 0.3);
604	
605	  /* ──────────────────────────────────────────────────────────
606	     PAYROLL STATS ROW (Sprint 8)
607	  ────────────────────────────────────────────────────────── */
608	  --color-payroll-stat-gross:  oklch(72% 0.18 292);
609	  --color-payroll-stat-net:    oklch(58% 0.18 145);
610	  --color-payroll-stat-deduct: oklch(55% 0.22 27);
611	
612	  /* ──────────────────────────────────────────────────────────
613	     MARK PAID MODAL WARNING (Sprint 8)
614	  ────────────────────────────────────────────────────────── */
615	  --color-lock-warning-bg:     oklch(55% 0.22 27 / 0.08);
616	  --color-lock-warning-border: oklch(55% 0.22 27 / 0.25);
617	  --color-lock-warning-text:   oklch(65% 0.18 27);
618	
619	  /* ──────────────────────────────────────────────────────────
620	     MOTION — DURATION TOKENS (Nova convergence 2026-04-17)
621	  ────────────────────────────────────────────────────────── */
622	  --duration-instant: 80ms;   /* hover tint, selection highlight, tooltip open */
623	  --duration-fast:    120ms;  /* button press scale, checkbox, toast slide-in */
624	  --duration-base:    180ms;  /* dropdown, popover, inline transitions */
625	  --duration-slow:    260ms;  /* dialog enter, drawer slide, skeleton exit */
626	  --duration-page:    320ms;  /* view transitions (list → detail crossfade) */
627	
628	  /* ──────────────────────────────────────────────────────────
629	     MOTION — EASING TOKENS
630	  ────────────────────────────────────────────────────────── */
631	  --ease-standard:   cubic-bezier(0.22, 1, 0.36, 1);  /* 95% of motion — snappy decel */
632	  --ease-emphasized: cubic-bezier(0.32, 0.72, 0, 1);  /* dialogs, drawers, longer tail */
633	  --ease-linear:     linear;                           /* shimmer, progress bars */
634	
635	  /* ──────────────────────────────────────────────────────────
636	     SKELETON / SHIMMER TOKENS
637	  ────────────────────────────────────────────────────────── */
638	  --shimmer-duration:  1600ms;
639	  --shimmer-bg:        oklch(from var(--color-background) calc(l - 0.04) c h);
640	  --shimmer-highlight: oklch(100% 0 0 / 0.06);   /* light mode — overlay sweep */
641	
642	  /* ──────────────────────────────────────────────────────────
643	     SKELETON — KEYFRAMES (Linear two-layer shimmer)
644	  ────────────────────────────────────────────────────────── */
645	  @keyframes shimmer-base {
646	    0%, 100% { opacity: 0.6; }
647	    50%       { opacity: 1; }
648	  }
649	
650	  @keyframes shimmer-sweep {
651	    from { background-position: 200% center; }
652	    to   { background-position: -200% center; }
653	  }
654	
655	  /* ──────────────────────────────────────────────────────────
656	     OPTIMISTIC UI — rollback pulse keyframe
657	  ────────────────────────────────────────────────────────── */
658	  @keyframes rollback-pulse {
659	    0%, 100% { border-color: transparent; }
660	    50%       { border-color: var(--color-destructive); }
661	  }
662	}
663	
664	/* ──────────────────────────────────────────────────────────
665	   DARK MODE — .dark class (manual theme toggle via next-themes)
666	────────────────────────────────────────────────────────── */
667	.dark {
668	  --color-background: oklch(11% 0.012 264);
669	  --color-foreground: oklch(95% 0.008 264);
670	  --color-card: oklch(14.5% 0.014 264);
671	  --color-card-foreground: oklch(95% 0.008 264);
672	  --color-popover: oklch(14.5% 0.014 264);
673	  --color-popover-foreground: oklch(95% 0.008 264);
674	  --color-primary: oklch(65% 0.24 292);
675	  --color-primary-foreground: oklch(10% 0.01 292);
676	  --color-secondary: oklch(20% 0.02 292);
677	  --color-secondary-foreground: oklch(85% 0.04 292);
678	  --color-muted: oklch(18% 0.015 264);
679	  --color-muted-foreground: oklch(60% 0.02 264);
680	  --color-accent: oklch(20% 0.04 292);
681	  --color-accent-foreground: oklch(80% 0.06 292);
682	  --color-destructive: oklch(62% 0.22 27);
683	  --color-destructive-foreground: oklch(99% 0 0);
684	  --color-border: oklch(22% 0.015 264);
685	  --color-input: oklch(22% 0.015 264);
686	  --color-ring: oklch(65% 0.24 292);
687	  --color-page-bg: oklch(11% 0.012 264);
688	  --color-header-bg: oklch(14.5% 0.014 264);
689	  --color-surface-1: oklch(14.5% 0.014 264);
690	  --color-surface-2: oklch(17% 0.016 264);
691	  --shadow-soft:    0 1px 2px 0 oklch(0% 0 0 / 0.25), 0 1px 3px 0 oklch(0% 0 0 / 0.18);
692	  --shadow-soft-md: 0 4px 16px -4px oklch(0% 0 0 / 0.35), 0 2px 8px -2px oklch(0% 0 0 / 0.22);
693	  --shadow-lift:    0 8px 24px -4px oklch(0% 0 0 / 0.50), 0 4px 10px -2px oklch(0% 0 0 / 0.30);
694	  --shadow-overlay: 0 24px 64px -12px oklch(0% 0 0 / 0.65), 0 8px 24px -4px oklch(0% 0 0 / 0.40);
695	  --shadow-card: 0 1px 3px 0 oklch(0% 0 0 / 0.3), 0 1px 2px -1px oklch(0% 0 0 / 0.2);
696	  --shadow-card-hover: 0 4px 12px -2px oklch(0% 0 0 / 0.4), 0 2px 6px -2px oklch(0% 0 0 / 0.3);
697	  /* ── Status tokens dark mode ── */
698	  --color-success:            oklch(62% 0.18 145);
699	  --color-success-bg:         oklch(20% 0.06 145);
700	  --color-success-foreground: oklch(82% 0.12 145);
701	  --color-warning:            oklch(72% 0.16 72);
702	  --color-warning-bg:         oklch(22% 0.07 72);
703	  --color-warning-foreground: oklch(86% 0.12 72);
704	  --sidebar: oklch(14.5% 0.014 264);
705	  --sidebar-background: oklch(14.5% 0.014 264);
706	  --sidebar-foreground: oklch(85% 0.01 264);
707	  --sidebar-primary: oklch(65% 0.24 292);
708	  --sidebar-primary-foreground: oklch(10% 0.01 292);
709	  --sidebar-accent: oklch(20% 0.04 292);
710	  --sidebar-accent-foreground: oklch(80% 0.06 292);
711	  --sidebar-border: oklch(22% 0.015 264);
712	}
713	
714	@layer base {
715	  *,
716	  *::before,
717	  *::after {
718	    border-color: var(--color-border);
719	    outline-color: var(--color-ring);
720	  }
721	
722	  html {
723	    -webkit-font-smoothing: antialiased;
724	    -moz-osx-font-smoothing: grayscale;
725	    text-rendering: optimizeLegibility;
726	  }
727	
728	  body {
729	    background-color: var(--color-background);
730	    color: var(--color-foreground);
731	    font-family: var(--font-sans);
732	  }
733	
734	  h1 {
735	    font-size: var(--text-h1-size);
736	    line-height: var(--text-h1-height);
737	    font-weight: var(--text-h1-weight);
738	    letter-spacing: var(--text-h1-track);
739	  }
740	
741	  h2 {
742	    font-size: var(--text-h2-size);
743	    line-height: var(--text-h2-height);
744	    font-weight: var(--text-h2-weight);
745	    letter-spacing: var(--text-h2-track);
746	  }
747	
748	  h3 {
