   DARK MODE — single authoritative .dark block (Sprint 4)
   Philosophy: Linear/Notion dark — NOT pitch black.
   Background L15, card L20, border L28. Warm slate hue 264.
────────────────────────────────────────────────────────── */
.dark {
  /* ── Core semantic ── */
  --color-background:          oklch(15% 0.01 264);
  --color-foreground:          oklch(95% 0.005 264);
  --color-card:                oklch(20% 0.015 264);
  --color-card-foreground:     oklch(95% 0.005 264);
  --color-popover:             oklch(20% 0.015 264);
  --color-popover-foreground:  oklch(95% 0.005 264);

  --color-primary:             oklch(65% 0.24 292);
  --color-primary-foreground:  oklch(99% 0 0);

  --color-secondary:           oklch(24% 0.015 264);
  --color-secondary-foreground: oklch(88% 0.01 264);

