  --color-surface-elevated:    oklch(30% 0.015 264);

  /* ── Shadows (stronger alpha — dark bg absorbs shadow) ── */
  --shadow-soft:       0 1px 3px oklch(0% 0 0 / 0.3), 0 1px 2px -1px oklch(0% 0 0 / 0.22);
  --shadow-card:       0 1px 4px oklch(0% 0 0 / 0.25), 0 2px 8px -2px oklch(0% 0 0 / 0.2);
  --shadow-card-hover: 0 8px 25px oklch(0% 0 0 / 0.35), 0 0 0 1px oklch(65% 0.24 292 / 0.2), inset 0 1px 0 oklch(100% 0 0 / 0.05);
