### Implementation

```typescript
// lib/charts/theme.ts
'use client'

import { useTheme } from 'next-themes'

export interface ChartTheme {
  axis: string
  grid: string
  text: string
  tooltip: {
    background: string
    border: string
    text: string
    secondaryText: string
  }
  series: readonly [string, string, string, string, string, string, string, string]
  sparkline: string
}

export function getChartTheme(isDark: boolean): ChartTheme {
  if (isDark) {
    return {
      axis:    'oklch(38% 0.012 264)',
      grid:    'oklch(28% 0.02 264)',
      text:    'oklch(66% 0.015 264)',
      tooltip: {
        background:    'oklch(20% 0.015 264)',
        border:        'oklch(28% 0.02 264)',
        text:          'oklch(95% 0.005 264)',
        secondaryText: 'oklch(66% 0.015 264)',
      },
      series: [
        'oklch(65% 0.24 292)',
        'oklch(68% 0.22 230)',
        'oklch(66% 0.18 145)',
        'oklch(72% 0.16 72)',
        'oklch(62% 0.22 27)',
        'oklch(68% 0.24 340)',
        'oklch(66% 0.2 200)',
        'oklch(70% 0.16 280)',
      ] as const,
      sparkline: 'oklch(65% 0.24 292)',
    }
  }
  return {
    axis:    'oklch(82% 0.008 264)',
    grid:    'oklch(91% 0.008 264)',
    text:    'oklch(52% 0.02 264)',
    tooltip: {
      background:    'oklch(100% 0 0)',
      border:        'oklch(91% 0.008 264)',
      text:          'oklch(13% 0.015 264)',
      secondaryText: 'oklch(52% 0.02 264)',
    },
    series: [
      'oklch(52% 0.24 292)',
      'oklch(60% 0.22 230)',
      'oklch(58% 0.18 145)',
      'oklch(62% 0.22 40)',
      'oklch(55% 0.22 27)',
      'oklch(60% 0.24 340)',
      'oklch(58% 0.2 200)',
      'oklch(62% 0.16 280)',
    ] as const,
    sparkline: 'oklch(52% 0.24 292)',
  }
}

/** Hook — resolves theme and returns typed chart theme. Use in 'use client' components. */
export function useChartTheme(): ChartTheme {
  const { resolvedTheme } = useTheme()
  return getChartTheme(resolvedTheme === 'dark')
}
```

### Chart component update pattern

Every Recharts consumer follows this pattern:

```tsx
'use client'
import { useChartTheme } from '@/lib/charts/theme'

export function SomeChart() {
  const ct = useChartTheme()
  return (
    <ResponsiveContainer width="100%" height={300}>
      <AreaChart data={data}>
        <CartesianGrid
          strokeDasharray="3 3"
          stroke={ct.grid}
          vertical={false}        // horizontal grid only
        />
        <XAxis
          stroke={ct.axis}
          tick={{ fill: ct.text, fontSize: 12 }}
        />
        <YAxis
          stroke={ct.axis}
          tick={{ fill: ct.text, fontSize: 12 }}
        />
        <Tooltip
          contentStyle={{
            background: ct.tooltip.background,
            border: `1px solid ${ct.tooltip.border}`,
            borderRadius: '0.5rem',
            boxShadow: 'var(--shadow-lift)',
          }}
          labelStyle={{ color: ct.tooltip.secondaryText, fontSize: 12 }}
          itemStyle={{ color: ct.tooltip.text, fontSize: 13 }}
        />
        <Area
          stroke={ct.series[0]}
          fill={ct.series[0]}
          fillOpacity={0.15}
        />
      </AreaChart>
    </ResponsiveContainer>
  )
}
```

Apply this pattern to all 7 Recharts consumer files. Replace any hardcoded hex colors on Recharts props (`stroke`, `fill`, `tick.fill`, `contentStyle.background`, etc.) with `ct.*` references. The `RechartsAreaChart.tsx` and `RechartsBarChart.tsx` primitives must accept `theme?: ChartTheme` as an optional prop and call `useChartTheme()` internally when prop is absent.

